import React from 'react';

import { render, screen } from '@testing-library/react';

import SkeletonLoader from './SkeletonLoader';

describe('SkeletonLoader', () => {
  it('should render without crashing', () => {
    render(
      <SkeletonLoader width="100px" height="75px" variant="body" data-testid="skeleton-loader" />
    );

    expect(screen.getByTestId('skeleton-loader')).toBeInTheDocument();
  });

  it('should render image variant without crashing', () => {
    render(<SkeletonLoader width="100px" height="75px" variant="image" />);

    expect(screen.getByAltText('skeleton loader')).toBeInTheDocument();
  });
});
